5	describe("firebaseConfigValidate", () => {
6	  it("should accept a basic, valid config", () => {
7	    const config: FirebaseConfig = {
8	      database: {
9	        rules: "myrules.json",
10	      },
11	      hosting: {
12	        public: "public",
13	      },
14	      emulators: {
15	        database: {
16	          port: 8080,
17	        },
18	      },
19	    };
20	
21	    const validator = getValidator();
22	    const isValid = validator(config);
23	
24	    expect(isValid).to.be.true;
25	  });
26	
27	  it("should report an extra top-level field", () => {
28	    // This config has an extra 'bananas' top-level property
29	    const config = {
30	      database: {
31	        rules: "myrules.json",
32	      },
33	      bananas: {},
34	    };
35	
36	    const validator = getValidator();
37	    const isValid = validator(config);
38	
39	    expect(isValid).to.be.false;
40	    expect(validator.errors).to.exist;
41	    expect(validator.errors!.length).to.eq(1);
42	
43	    const firstError = validator.errors![0];
44	    expect(firstError.keyword).to.eq("additionalProperties");
45	    expect(firstError.dataPath).to.eq("");
46	    expect(firstError.params).to.deep.equal({ additionalProperty: "bananas" });
47	  });
48	
